const E=Engine,STORE='agent-studio-prd-1.3';
let S;try{S=JSON.parse(localStorage.getItem(STORE));if(S?.schema!==13)S=null}catch{}S=S||E.initial();
S.evalTasks=S.evalTasks||[];S.datasets=S.datasets||[];S.apps.forEach((a,i)=>{if(!a.owner)a.owner=['林晓','周宁','陈思远'][i]||'未指定'});
let page='list',appId='A',buffer=null,dirty=false,nodeId='',testScenario='normal',selectedVersion='',runFilter='全部',filter='全部',search='',lastRun=null;
const app=()=>S.apps.find(a=>a.id===appId)||S.apps[0],cfg=()=>buffer||app().draft;
const pageNames={list:'应用工作台',build:'配置与流程',versions:'版本与依赖',eval:'评测报告',release:'发布管理',runs:'运行记录',batches:'批任务',knowledge:'知识与政策',assets:'模板与接入资产',audit:'权限与审计'};
const persist=()=>{try{localStorage.setItem(STORE,JSON.stringify(S))}catch{toast('本地存储空间不足，请导出或重置演示数据')}};
function toast(t){let el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>el.classList.remove('show'),3000)}
function act(fn){try{fn();persist()}catch(e){toast(e.message)}}
const badge=(t,c='')=>`<span class="badge ${c}">${esc(t)}</span>`;
const button=(t,fn,c='',disabled=false)=>`<button class="btn ${c}" onclick="${esc(fn)}" ${disabled?'disabled':''}>${t}</button>`;
const options=(items,val)=>items.map(x=>{let [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===val?'selected':''}>${esc(t)}</option>`}).join('');
function field(label,id,value,type='text',extra=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function select(label,id,items,value,change=''){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" ${change?`onchange="${change}"`:''}>${options(items,value)}</select></div>`}
function modal(title,body,footer=''){document.querySelector('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="plain" onclick="closeModal()" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div><div class="modal-footer">${footer||button('关闭','closeModal()')}</div></section></div>`;document.querySelector('.modal button')?.focus()}
function closeModal(){document.querySelector('#overlay').innerHTML=''}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function go(p,id=appId){if(dirty){modal('未保存的草稿',`<p>离开前可保存当前修改，或放弃尚未保存的配置。生产版本不受影响。</p>`,button('继续编辑','closeModal()')+button('放弃修改',`dirty=false;buffer=null;closeModal();go('${p}','${id}')`)+button('保存并离开',`act(()=>{saveDraft();closeModal();go('${p}','${id}')})`,'primary'));return}appId=id;page=p;buffer=page==='build'?E.copy(app().draft):null;nodeId='';selectedVersion=app().candidate||app().production;location.hash=p+(p==='list'?'':'/'+appId);render();window.scrollTo(0,0)}
function change(k,v,redraw=false){if(S.role!=='业务编辑者'){toast('请切换业务编辑者');render();return}buffer=buffer||E.copy(app().draft);buffer[k]=v;dirty=true;document.querySelector('#draft-status')&&(document.querySelector('#draft-status').textContent='未保存修改');if(redraw)render()}
function saveDraft(){E.save(S,app(),cfg());buffer=E.copy(app().draft);dirty=false;persist();render();toast('草稿已保存，生产保持不变')}
function freeze(){act(()=>{if(dirty)throw Error('请先保存草稿，再固化版本');let id=E.freeze(S,app());selectedVersion=id;render();toast(id+' 已固化，请前往评测')})}
function stat(t,v,n,ico='box'){return `<div class="stat"><div class="stat-label">${t}${icon(ico)}</div><div class="stat-value">${v}</div><div class="stat-note">${n}</div></div>`}
function render(){const a=app();document.title=pageNames[page]+' · Agent Studio V1.3';let global=['list','knowledge','assets','audit'].includes(page);document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#list" onclick="event.preventDefault();go('list')"><span class="brandmark">${icon('box')}</span>Agent Studio</a><div class="workspace">${icon('users')}统一 Agent 演示项目</div><div class="nav-label">工作空间</div>${[['list','grid'],['build','box'],['versions','clock'],['eval','flask'],['release','send'],['runs','chart'],['batches','grid']].map(([p,i])=>`<button class="nav-item ${p===page?'active':''}" onclick="go('${p}')">${icon(i)}${pageNames[p]}</button>`).join('')}<div class="nav-separator"></div><div class="nav-label">共享能力</div>${[['knowledge','book'],['assets','tool'],['audit','shield']].map(([p,i])=>`<button class="nav-item ${p===page?'active':''}" onclick="go('${p}')">${icon(i)}${pageNames[p]}</button>`).join('')}<div class="sidebar-bottom"><div class="demo-card"><b>PRD V1.3 · 评审环境</b>原子能力复用 · 统一生产管理<button onclick="guide()">查看评审路径 →</button><br><button onclick="resetDemo()">重置演示数据</button></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><button class="plain mobile-menu" aria-label="菜单" onclick="document.querySelector('.sidebar').classList.toggle('open')">${icon('menu')}</button>工作空间 / <b>${pageNames[page]}</b></div><div class="top-tools"><span class="pill">演示环境 · 模拟数据</span><select aria-label="演示角色" class="select role-select" onchange="switchRole(this.value)">${options(['业务编辑者','发布者','指定审批人'],S.role)}</select></div></header><div class="content">${global?'':`<div class="heading"><div><div class="eyebrow">APPLICATION / ${a.id}</div><h1>${esc(a.name)} ${badge(a.grayPercent?'灰度运行':a.active?'正式运行':'未上线 / 已停用',a.grayPercent?'warning':a.active?'':'neutral')}</h1><p class="subtitle">生产 ${a.production||'—'} · 草稿 r${a.revision} · ${a.draft.execution==='online'?'在线调用':'批量任务'} ${a.draft.sessions?'· 多轮会话':''}</p></div><select class="select select-inline" aria-label="切换应用" onchange="go(page,this.value)">${options(S.apps.map(x=>[x.id,x.name]),a.id)}</select></div><div class="app-tabs">${['build','versions','eval','release','runs','batches'].map(p=>`<button class="${p===page?'active':''}" onclick="go('${p}')">${pageNames[p]}</button>`).join('')}</div>`}${({list:home,build:build,versions:versions,eval:evaluation,release:releases,runs:runs,batches:batches,knowledge:knowledge,assets:assets,audit:audit})[page]()}<footer class="footnote"><span>依据 PRD V1.3 · 本地评审状态自动保存</span><span>不调用真实模型、业务接口或生产服务</span></footer></div></main></div>`;}
function switchRole(role){if(dirty){toast('请先保存或放弃当前草稿');render();return}S.role=role;persist();render()}
function home(){return `<div class="heading"><div><div class="eyebrow">WORKSPACE OVERVIEW / V1.3</div><h1>应用工作台</h1><p class="subtitle">组合原子能力，构建适合业务的 Agent。</p></div>${button(icon('plus')+'创建应用','createDialog()','primary')}</div><div class="stats">${stat('应用总数',S.apps.length+'<small>个</small>','三种构建入口，统一版本管理')}${stat('生产运行',S.apps.filter(a=>a.active).length+'<small>个</small>','在线与批量分别调度','zap')}${stat('评审运行记录',S.runs.length+'<small>条</small>','测试环境与生产模拟隔离','chart')}${stat('共享资产',S.assets.length+S.templates.length+S.services.length+'<small>项</small>','知识 · 模板 · Skill · 接口','book')}</div><section class="panel"><div class="panel-head"><h2>我的应用 <span class="count">${S.apps.length}</span></h2><label class="search">${icon('search')}<input aria-label="搜索应用" placeholder="搜索应用名称" value="${esc(search)}" oninput="search=this.value;document.querySelector('#app-rows').innerHTML=appRows()"></label></div><div class="table-wrap"><table><thead><tr><th>应用 / 构建方式</th><th>执行与会话</th><th>生产版本 / 流量</th><th>草稿与候选</th><th>操作</th></tr></thead><tbody id="app-rows">${appRows()}</tbody></table></div></section><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>三条评审路径</h2><span class="pill">能力按需组合</span></div><div class="review-flows">${[['A','流程策略 → 分支调试 → 灰度 → 回退'],['B','分类规则 → 评测拦截 → 审批 → 批任务'],['C','知识问答 → 流程扩展 → 知识更新 → 会话绑定']].map(([id,t])=>`<button class="flow-link" onclick="go('build','${id}')"><span class="flow-letter">${id}</span><span><b>${S.apps.find(a=>a.id===id).name}</b><small>${t}</small></span>${icon('arrow')}</button>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>本次版本变化</h2><span class="tag">PRD V1.3</span></div><div class="panel-body"><div class="dependency">${icon('box')}固定模板 → 可编辑的原子节点流程</div><div class="dependency">${icon('tool')}增加 Skill 版本绑定与受控服务接入</div><div class="dependency">${icon('shield')}执行、会话、审批和灰度独立配置</div><p class="muted">高级循环、并行、子流程、自主 Skill 调度与代码托管仍属二期。</p></div></section></div>`}
function appRows(){return S.apps.filter(a=>a.name.includes(search)).map(a=>`<tr><td><div class="agent-name"><span class="agent-icon ${a.kind}">${icon(a.kind==='A'?'spark':a.kind==='B'?'shield':'book')}</span><span><strong>${esc(a.name)}</strong><small>${modeLabel(a.draft.mode)} · ${esc(a.team)} · 责任人：${esc(a.owner||'未指定')}</small></span></div></td><td>${a.draft.execution==='batch'?'批量':'在线'} · ${a.draft.sessions?'多轮':'单轮'}<small class="row-small">${a.draft.approval?'需审批':'无需审批'} / ${a.draft.gray?'可灰度':'全量发布'}</small></td><td><span class="tag">${a.production||'未上线'}</span> ${a.active?100-a.grayPercent:0}%${a.grayVersion?`<small class="row-small purple">${a.grayVersion} · ${a.grayPercent}%</small>`:''}</td><td>r${a.revision}<small class="row-small">${a.candidate?'候选 '+a.candidate:'待固化'} · ${a.candidate&&E.version(a,a.candidate)?.report?'已评测':'待验证'}</small></td><td><button class="link" onclick="go('build','${a.id}')">管理 →</button> <button class="link" onclick="renameAppDialog('${a.id}')">重命名</button> <button class="link danger-text" onclick="deleteAppDialog('${a.id}')">删除</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">没有匹配的应用</td></tr>'}
function renameAppDialog(id){let a=S.apps.find(x=>x.id===id);modal('重命名应用',field('应用名称','rename-name',a.name),button('取消','closeModal()')+button('保存','commitRename(\''+id+'\')','primary'))}
function commitRename(id){act(()=>{let a=S.apps.find(x=>x.id===id),name=document.querySelector('#rename-name').value.trim();if(!name||S.apps.some(x=>x.id!==id&&x.name===name))throw Error('名称必填且项目内唯一');a.name=name;E.log(S,a,'应用重命名为 '+name);closeModal();render();toast('应用名称已更新')})}
function deleteAppDialog(id){let a=S.apps.find(x=>x.id===id);modal('删除应用',`<p>将删除「${esc(a.name)}」及其草稿、版本、评测和运行记录。该操作仅作用于本地演示数据。</p>`,button('取消','closeModal()')+button('确认删除','deleteApp(\''+id+'\')','danger'))}
function deleteApp(id){act(()=>{if(S.apps.length<=1)throw Error('至少保留一个应用');let a=S.apps.find(x=>x.id===id);S.apps=S.apps.filter(x=>x.id!==id);S.runs=S.runs.filter(x=>x.appId!==id);S.sessions=S.sessions.filter(x=>x.appId!==id);S.batches=S.batches.filter(x=>x.appId!==id);S.evalTasks=(S.evalTasks||[]).filter(x=>x.appId!==id);closeModal();if(appId===id){appId=S.apps[0].id;page='list';location.hash='#list'}render();toast('应用已删除')})}
function ownerField(id,value){return select('责任人',id,[['','请选择责任人'],['林晓','林晓'],['周宁','周宁'],['陈思远','陈思远'],['王一','王一'],['赵可','赵可']],value||'')}
const modeLabel=m=>({simple:'简单配置',flow:'基础编排',service:'受控服务接入'})[m];
function controls(c){return `<div class="settings-row">${select('执行方式','execution',[['online','在线调用'],['batch','批量任务']],c.execution,"change('execution',this.value)")}${select('会话上下文','sessions',[['off','单轮'],['on','多轮']],c.sessions?'on':'off',"change('sessions',this.value==='on')")}${select('发布审批','approval',[['off','不需要'],['on','指定审批']],c.approval?'on':'off',"change('approval',this.value==='on')")}${select('发布策略','gray',[['off','全量'],['on','支持两版本灰度']],c.gray?'on':'off',"change('gray',this.value==='on')")}</div>`}
function buildVersionPicker(){let a=app(),items=[['draft','当前草稿 · r'+a.revision],...a.versions.map(v=>[v.id,v.id+(v.id===a.production?' · 生产':'')])];return `<div class="version-switcher">${select('配置版本','build-version',items,'draft','switchBuildVersion(this.value)')}<span class="muted">历史版本只读；载入后会复制为新草稿</span></div>`}
function switchBuildVersion(id){if(id==='draft')return;let v=E.version(app(),id);if(!v)return;modal('载入版本配置',`<p>将 ${id} 的完整配置（节点、依赖、模型与字段契约）复制到当前草稿，生产版本和历史快照不变。</p>`,button('取消','closeModal()')+button('复制到草稿',`act(()=>{E.save(S,app(),E.copy(E.version(app(),'${id}').config));buffer=E.copy(app().draft);dirty=false;closeModal();render();toast('${id} 已载入草稿，请重新检查与固化')})`,'primary'))}
function build(){let a=app(),c=cfg();return `<div class="build-status"><div><span class="tag">${modeLabel(c.mode)}</span> <b id="draft-status">${dirty?'未保存修改':'草稿 r'+a.revision+' 已保存'}</b><small>责任人：${esc(a.owner||'未指定')} · 生产 ${a.production||'未上线'} 不受草稿影响</small></div><div class="actions">${c.mode==='simple'?button('转换为可编辑流程','convert()','small'):''}${button('保存草稿','act(saveDraft)','small',S.role!=='业务编辑者')}${button('静态检查','staticCheck()','small')}${button('完整试运行','debugDialog()','small')}${button('固化版本','freeze()','primary small',dirty||S.role!=='业务编辑者')}</div></div>${buildVersionPicker()}${controls(c)}${c.mode==='flow'?flow(c):form(c)}<div class="actions" style="margin-top:20px">${button('版本与依赖 →',"go('versions')")}${button('前往评测 →',"go('eval')",'primary')}${button('保存为共享模板','saveTemplateDialog()','',dirty)}</div>`}
function form(c){return `<div class="detail-grid"><section class="panel"><div class="panel-head"><h2>${c.mode==='service'?'受控接口配置':'内置执行流程'}</h2><span class="tag">${c.mode==='service'?'接口边界可见':c.preset==='single'?'单次模型':'检索问答'}</span></div><div class="panel-body">${c.mode==='service'?select('绑定服务版本','service',[['','请选择已注册服务'],...S.services.map(x=>[x.id,x.id+' · '+x.name])],c.service,"bindService(this.value)"):''}<div class="field"><label for="prompt">任务说明 / 提示词</label><textarea id="prompt" oninput="changePrompt(this.value)">${esc(c.prompt)}</textarea></div>${select('模型网关','model',['company-chat-standard','company-chat-quality'],c.model,"change('model',this.value)")}<div class="fields-row">${field('温度','temp',c.temperature,'number',`min="0" max="1" step="0.1" onchange="change('temperature',+this.value)"`)}${field('超时（秒）','timeout',c.timeout,'number',`min="1" max="60" onchange="change('timeout',+this.value)"`)}</div>${app().kind==='B'?`<label class="switch-row"><input type="checkbox" ${c.rule?'checked':''} onchange="change('rule',this.checked)">识别变体联系方式与隐晦引流</label>`:''}${contracts(c)}</div></section><section class="panel"><div class="panel-head"><h2>依赖与规则</h2></div><div class="panel-body">${dependencyForm(c)}<div class="notice">${icon('shield')}输出类别与理由仅辅助审核，客服回答仅辅助人工。平台不直接处罚、退款或执行任意脚本。</div><h3>当前执行步骤</h3>${c.mode==='service'?'<div class="dependency">版本化接口 → 返回契约 → externalTraceId</div>':c.nodes.filter(n=>n.type!=='fallback').map(n=>`<button class="dependency dependency-button" onclick="nodeId='${n.id}';nodeTest()">${esc(n.name)}<span>单节点测试 →</span></button>`).join('')}<p class="muted">参数、引用、实际路径与错误记录均可在调试详情查看。</p></div></section></div>`}
function contracts(c){return `<details class="contract"><summary>输入输出契约 · 字段类型</summary><div class="field"><label for="inputSchema">输入字段</label><textarea id="inputSchema" oninput="change('inputSchema',this.value)">${esc(c.inputSchema)}</textarea></div><div class="field"><label for="outputSchema">输出字段</label><textarea id="outputSchema" oninput="change('outputSchema',this.value)">${esc(c.outputSchema)}</textarea></div></details>`}
function dependencyForm(c){return `${select('知识 / 政策快照','knowledge',[['','不使用'],...S.assets.filter(x=>['knowledge','policy'].includes(x.type)).map(x=>[x.id,x.name+' · '+x.id+(x.valid?'':'（已失效）')])],c.knowledge,"change('knowledge',this.value)")}${select('显式绑定 Skill 版本','skill',[['','不使用'],...S.assets.filter(x=>x.type==='skill').map(x=>[x.id,x.name+' · '+x.id])],c.skill,"bindSkill(this.value)")}<div class="dependency">模板来源<span>${esc(c.template||'空白创建')}</span></div><p class="muted">依赖升级只写入草稿，需重新固化和评测。Skill 是说明与参考资料，不能授予权限或执行代码。</p>`}
function changePrompt(v){change('prompt',v);cfg().nodes.filter(n=>n.type==='model').forEach(n=>n.prompt=v)}
function bindSkill(v){change('skill',v);let n=cfg().nodes.find(n=>n.type==='model');if(n)n.skill=v}
function bindService(v){change('service',v);render()}
function convert(){modal('转换为基础流程',`<p>保留当前提示词、字段契约、模型、知识、会话和发布规则。转换后可以编辑节点与连线，需要保存并重新验证。</p><p>一期不支持任意流程反向转换为简单表单。</p>`,button('取消','closeModal()')+button('确认转换',"change('mode','flow');closeModal();render()",'primary'))}
function flow(c){let selected=c.nodes.find(n=>n.id===nodeId)||c.nodes[0];if(selected)nodeId=selected.id;return `<div class="flow-editor"><aside class="node-library"><h3>原子节点</h3><p class="muted">点击添加到画布</p>${Object.entries(E.types).filter(([k])=>k!=='service').map(([k,t])=>`<button onclick="addNode('${k}')">${icon(k==='model'?'spark':k==='tool'?'tool':'box')}${t}<span>+</span></button>`).join('')}<div class="nav-separator"></div>${button('连接节点','connectDialog()','small')}${aKind('C')?button('添加物流分支','addLogistics()','small'):''}<p class="muted">顺序与条件执行<br>高级循环 / 并行为二期</p></aside><section class="canvas"><div class="canvas-heading"><b>执行流程</b><span>${c.nodes.length} 个节点 · ${c.edges.length} 条连线</span></div><div class="node-grid">${c.nodes.map(n=>`<button class="flow-node ${n.id===nodeId?'selected':''} ${lastRun?.steps.some(s=>s.id===n.id)?'executed':''}" onclick="nodeId='${n.id}';render()"><span class="node-type">${icon(n.type==='model'?'spark':n.type==='tool'?'tool':'box')}${E.types[n.type]}</span><b>${esc(n.name)}</b><small>${esc(n.id)}${n.skill?' · '+esc(n.skill):''}</small></button>`).join('')||'<div class="empty">空白画布 · 从左侧添加输入、模型、输出和异常出口</div>'}</div><div class="connections"><h3>连线与分支</h3>${c.edges.map((e,i)=>`<div class="connection"><span>${esc(e.from)} <b>${e.port==='yes'?'是':e.port==='no'?'否':'→'}</b> ${esc(e.to)}</span><button class="plain" aria-label="删除连线 ${esc(e.from)} 到 ${esc(e.to)}" onclick="removeEdge(${i})">×</button></div>`).join('')}<p class="muted">工具 / 模型的异常跳转在节点配置中设置。</p></div></section><aside class="node-inspector"><h3>节点配置</h3>${selected?nodeForm(selected,c):'<p class="muted">选择或添加一个节点</p>'}</aside></div><details class="panel common-config"><summary>全局依赖、模型与字段契约</summary><div class="panel-body"><div class="fields-row"><div>${dependencyForm(c)}</div><div>${contracts(c)}${select('模型网关','flowmodel',['company-chat-standard','company-chat-quality'],c.model,"change('model',this.value)")}${field('超时（秒）','flowtimeout',c.timeout,'number',`onchange="change('timeout',+this.value)"`)}</div></div></div></details>`}
function aKind(k){return app().kind===k}
function nodeForm(n,c){return `<span class="tag">${n.id} · ${E.types[n.type]}</span>${field('节点名称','node-name',n.name,'text',`oninput="editNode('name',this.value)"`)}${!['input','fallback'].includes(n.type)?field('输入变量映射','node-map',n.map,'text',`oninput="editNode('map',this.value)"`):''}${n.type==='model'?`<div class="field"><label for="node-prompt">模型提示词</label><textarea id="node-prompt" oninput="editNode('prompt',this.value)">${esc(n.prompt)}</textarea></div>${select('Skill 固定版本','node-skill',[['','不使用'],...S.assets.filter(a=>a.type==='skill').map(a=>a.id)],n.skill,"editNode('skill',this.value)")}`:''}${n.type==='data'?select('检索策略','strategy',['热门优先','同款相关优先','近期优质优先'],c.strategy,"change('strategy',this.value)"):''}${n.type==='condition'?select('判断条件','condition',[['has_results','检索结果非空'],['is_logistics','问题包含物流意图']],n.condition,"editNode('condition',this.value)"):''}${n.type==='tool'?select('已授权工具','node-tool',S.assets.filter(a=>a.type==='tool').map(a=>[a.id,a.name+' · '+a.id]),n.tool,"editNode('tool',this.value)"):''}${['tool','knowledge','model','validate','service'].includes(n.type)?select('异常出口','fallback',[['','未设置'],...c.nodes.filter(n=>n.type==='fallback').map(n=>[n.id,n.name])],n.fallback,"editNode('fallback',this.value)"):''}<div class="actions">${button('测试节点','nodeTest()','small')}${button('删除节点','deleteNode()','danger small')}</div><p class="muted">映射示例：input.text 或 上游节点ID.output。权限由平台执行，不依赖 Skill 指令。</p>`}
function editNode(k,v){if(S.role!=='业务编辑者')return toast('请切换业务编辑者');cfg().nodes.find(n=>n.id===nodeId)[k]=v;dirty=true;document.querySelector('#draft-status').textContent='未保存修改'}
function addNode(type){if(S.role!=='业务编辑者')return toast('请切换业务编辑者');let id=type+'_'+Date.now().toString(36).slice(-5);cfg().nodes.push(E.node(id,type,E.types[type]));nodeId=id;dirty=true;render()}
function deleteNode(){if(S.role!=='业务编辑者')return toast('请切换业务编辑者');cfg().nodes=cfg().nodes.filter(n=>n.id!==nodeId);cfg().edges=cfg().edges.filter(e=>e.from!==nodeId&&e.to!==nodeId);dirty=true;nodeId='';render()}
function removeEdge(i){if(S.role!=='业务编辑者')return toast('请切换业务编辑者');cfg().edges.splice(i,1);dirty=true;render()}
function connectDialog(){let c=cfg();modal('连接节点',`${select('源节点','edge-from',c.nodes.map(n=>[n.id,n.name+' / '+n.id]),nodeId)}${select('源出口','edge-port',[['next','顺序出口'],['yes','条件为是'],['no','条件为否']],'next')}${select('目标节点','edge-to',c.nodes.map(n=>[n.id,n.name+' / '+n.id]),'')}`,button('取消','closeModal()')+button('添加连线','connect()','primary'))}
function connect(){if(S.role!=='业务编辑者')return toast('请切换业务编辑者');let from=document.querySelector('#edge-from').value,to=document.querySelector('#edge-to').value,port=document.querySelector('#edge-port').value;let n=cfg().nodes.find(n=>n.id===from);if(from===to)return toast('不能连接自身');if(n.type==='output')return toast('输出节点不能有后续连线');if((n.type==='condition')===(port==='next'))return toast('条件节点使用 yes/no，其余节点使用顺序出口');if(cfg().edges.some(e=>e.from===from&&e.port===port))return toast('该出口已有连线，请先移除');cfg().edges.push(E.edge(from,to,port));dirty=true;closeModal();render()}
function addLogistics(){if(S.role!=='业务编辑者')return toast('请切换业务编辑者');E.logistics(cfg());dirty=true;render();toast('已添加意图分支、物流工具与异常出口，可继续编辑')}
function staticCheck(){let errors=E.check(cfg(),S);let body=errors.length?'<div class="notice error">发现 '+errors.length+' 项问题，禁止完整试运行与固化。</div>'+errors.map(e=>`<button class="dependency dependency-button" onclick="closeModal();nodeId='${e.id}';render()">${esc(e.id||'全局')} · ${esc(e.message)}<span>定位 →</span></button>`).join(''):'<div class="notice success">检查通过：必填、字段类型、变量来源、连线、可达性、分支、异常出口与依赖均有效。</div>';modal('静态检查',body)}
function nodeTest(){let n=cfg().nodes.find(n=>n.id===nodeId);if(!n)return toast('请选择节点');modal('单节点测试 · '+n.name,`${field('测试输入','debug-input','测试业务问题')}`,button('取消','closeModal()')+button('执行节点',"doDebug(true)",'primary'))}
function debugDialog(){let errors=E.check(cfg(),S);if(errors.length)return staticCheck();modal('完整试运行 · 测试环境',`${select('模拟场景','debug-scenario',[['normal','正常输入'],['empty','检索无结果'],['timeout','工具超时（有限重试）'],['logistics_timeout','物流超时转人工'],['no_knowledge','无知识依据'],['invalid_reference','引用失效']],'normal')}${field('业务输入','debug-input',aKind('A')?'周末公园，简约休闲穿搭':aKind('B')?'使用变体联系方式引导站外交易':'这件衣服可以几天内退货？')}<p>仅执行当前草稿，不改变生产。物流超时场景请先添加物流查询分支并输入物流问题。</p>`,button('取消','closeModal()')+button('运行并查看路径','doDebug(false)','primary'))}
function doDebug(only){act(()=>{let c=cfg(),n=c.nodes.find(n=>n.id===nodeId);if(only){if(n.type==='model'&&!n.prompt.trim())throw Error('节点提示词必填');if(n.type==='tool'&&!S.assets.some(a=>a.id===n.tool&&a.authorized&&a.valid))throw Error('工具无权限或不存在')}let scenario=document.querySelector('#debug-scenario')?.value||'normal';lastRun=E.execute(S,app(),c,document.querySelector('#debug-input').value,scenario,{},only?nodeId:null);closeModal();render();showRun(lastRun.id)})}
function showRun(id){let r=S.runs.find(x=>x.id===id);modal('执行详情 · '+r.id,`<div class="notice">${r.environment} · ${r.versionId||'草稿 r'+r.revision} · ${r.status} · ${r.duration} ms<br>${r.sessionId||r.traceId}</div><div class="chips">${r.dependencies.map(d=>`<span class="tag">${esc(d)}</span>`).join('')}</div><h3 style="margin:20px 0">实际执行路径</h3><div class="trace-path">${r.steps.map(x=>`<span>${esc(x.name)}</span>`).join('<b>→</b>')}</div>${r.steps.map(x=>`<details class="trace-detail"><summary>${esc(x.name)} · ${x.duration} ms ${x.error?'<span class="red">'+esc(x.error)+'</span>':''}</summary><b>输入</b><pre class="code">${esc(JSON.stringify(x.input,null,2))}</pre><b>输出</b><pre class="code">${esc(JSON.stringify(x.output,null,2))}</pre>${x.reference?`<button class="link" onclick="source('${x.reference}')">引用 ${esc(x.reference)}</button>`:''}<p class="muted">映射：${esc(x.mapping||'接口契约')} ${x.skill?'· Skill '+esc(x.skill):''}</p></details>`).join('')}<h3 style="margin-top:20px">最终输出</h3><pre class="code">${esc(JSON.stringify(r.output,null,2))}</pre><p class="muted">未执行节点不生成输出；外部服务只显示接口边界与外部 traceId。</p>`,button('加入回归样本',`sampleDialog('${id}')`)+button('关闭','closeModal()','primary'))}
function versions(){let a=app();return `<div class="notice">${icon('shield')}版本固化执行流程、配置和依赖；从历史版本创建草稿不会更改原版本或覆盖生产。</div><section class="panel"><div class="panel-head"><h2>不可变版本</h2>${button('前往配置固化',"go('build')",'small')}</div><div class="table-wrap"><table><thead><tr><th>版本 / 来源</th><th>构建方式</th><th>固定依赖</th><th>评测 / 审批</th><th>操作</th></tr></thead><tbody>${a.versions.slice().reverse().map(v=>`<tr><td><strong>${v.id}</strong><small class="row-small">r${v.revision} · ${v.id===a.production?'生产':v.id===a.candidate?'当前候选':'历史版本'}</small></td><td>${modeLabel(v.config.mode)}</td><td class="wrap-cell">${E.deps(v.config).map(d=>`<span class="tag">${esc(d)}</span>`).join(' ')}</td><td>${badge(v.report?v.report.pass?'通过':'失败':'未评测',v.report?.pass?'':v.report?'error':'neutral')}<small class="row-small">${v.config.approval?v.approval:'无需审批'}</small></td><td><button class="link" onclick="versionDetails('${v.id}')">快照 / 差异</button><br><button class="link" onclick="fromVersion('${v.id}')">创建新草稿</button></td></tr>`).join('')}</tbody></table></div></section>`}
function versionDetails(id){let a=app(),v=E.version(a,id),base=E.version(a,a.production),c=v.config;modal('版本快照与差异 · '+id,`<p>来源 r${v.revision} · ${v.time}</p><table><tr><th>配置</th><th>生产 ${a.production||'—'}</th><th>${id}</th></tr>${['mode','knowledge','template','skill','model','execution','sessions','approval','gray','strategy'].map(k=>`<tr><td>${({mode:'构建',knowledge:'知识 / 政策',template:'模板',skill:'Skill',model:'模型',execution:'执行方式',sessions:'多轮会话',approval:'审批',gray:'灰度',strategy:'策略'})[k]}</td><td>${esc(base?.config[k]??'—')}</td><td class="${base?.config[k]!==c[k]?'purple':''}">${esc(c[k])}</td></tr>`).join('')}</table><details><summary>查看完整不可变配置</summary><pre class="code">${esc(JSON.stringify(c,null,2))}</pre></details>`)}
function fromVersion(id){act(()=>{if(S.role!=='业务编辑者')throw Error('请切换业务编辑者');E.save(S,app(),E.version(app(),id).config);app().candidate=null;go('build');toast('已复制到草稿，需重新固化与验证')})}
function versionPicker(){let a=app();if(!E.version(a,selectedVersion))selectedVersion=a.candidate||a.production;return select('评审目标版本','version-target',a.versions.map(v=>[v.id,v.id+(v.id===a.production?' · 当前生产':'')]),selectedVersion,"selectedVersion=this.value;render()");}
function datasetUpload(){modal('上传评测数据集',`${field('数据集名称','dataset-name','售后回归集')}${field('数据集版本','dataset-version','1')}${select('数据格式','dataset-format',[['jsonl','JSONL'],['csv','CSV'],['json','JSON']],'jsonl')}${field('样本数量','dataset-count','500','number')}<div class="field"><label for="dataset-file">选择文件（演示）</label><input id="dataset-file" type="file" accept=".jsonl,.csv,.json"></div><p class="muted">文件只在本地演示环境登记元数据，不上传到外部服务。数据集版本不可覆盖。</p>`,button('取消','closeModal()')+button('登记数据集','commitDataset()','primary'))}
function commitDataset(){act(()=>{let name=document.querySelector('#dataset-name').value.trim(),version=document.querySelector('#dataset-version').value.trim(),count=+document.querySelector('#dataset-count').value||0,file=document.querySelector('#dataset-file').files?.[0];if(!name||!version||count<1)throw Error('名称、版本和样本数量必填');let id='ds-'+app().id.toLowerCase()+'-'+version;if((S.datasets||[]).some(x=>x.id===id))throw Error('数据集版本已存在，请递增版本');S.datasets=S.datasets||[];S.datasets.unshift({id,name,version,format:document.querySelector('#dataset-format').value,count,fileName:file?.name||'演示登记',owner:S.role,time:new Date().toLocaleString('zh-CN')});app().dataset=id;E.log(S,app(),'登记评测数据集 '+id+'，后续评测需重新执行');closeModal();render();toast('数据集已登记并绑定当前应用')})}
function evalTasks(){let rows=(S.evalTasks||[]).filter(x=>x.appId===appId);return `<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>评测任务记录 <span class="count">${rows.length}</span></h2><span class="muted">责任人：${esc(app().owner||'未指定')}</span></div><div class="table-wrap"><table><thead><tr><th>任务</th><th>版本 / 数据集</th><th>责任人</th><th>状态</th><th>时间</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.id}<small class="row-small">${x.reportId}</small></td><td>${x.versionId}<small class="row-small">${x.datasetId}</small></td><td>${esc(x.owner)}</td><td>${badge(x.status,x.pass?'':'error')}</td><td>${esc(x.time)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无评测任务</td></tr>'}</tbody></table></div></section>`}
function evaluation(){let a=app(),v=E.version(a,selectedVersion||a.candidate||a.production),r=v?.report;return `<div class="review-toolbar">${versionPicker()}<div><b>数据集 ${a.dataset}</b><small>固定人工标签 · 500 条 · 门槛 r${a.ruleRevision}</small></div><div class="actions">${button('开始评测','runEvaluation()','primary',!v||S.role!=='业务编辑者')}${button('模拟执行失败','runEvaluation(true)','small',!v||S.role!=='业务编辑者')}${button('更新准入规则','updateRule()','small')}${button('历史评测','reportHistory()','small')}</div></div><div class="notice">${icon('flask')}阈值与结果均为评审示例，非确认的生产标准。${r?.historical?'当前为预置历史通过报告。':'评测绑定不可变版本，不会验证尚未固化的草稿。'}</div><section class="panel"><div class="panel-head"><h2>${!r?'尚未评测':r.error?'评测执行失败':r.pass?'评测通过':'关键指标未达标'}</h2>${badge(r?.pass?'通过':r?'未通过':'待执行',r?.pass?'':r?'error':'neutral')}</div>${r?.error?'<div class="panel-body"><div class="notice error">EVAL_TIMEOUT · 评测执行异常，可重新运行；发布保持拦截。</div></div>':''}<div class="table-wrap"><table><thead><tr><th>指标</th><th>示例门槛</th><th>生产基线</th><th>候选结果 / 样本</th><th>结论</th></tr></thead><tbody>${(r?.metrics||E.metrics(a.kind,v?.config||a.draft)).map(m=>`<tr><td><strong>${m[0]}</strong></td><td>${m[2]===0?'=':m[3]==='ms'?'≤':'≥'} ${m[2]} ${m[3]}</td><td>${baselineMetric(m[0])}</td><td>${r&&!r.error?m[1]+' '+m[3]+metricCount(m):'—'}</td><td>${r&&!r.error?badge(m[4]?'通过':'未达标',m[4]?'':'error'):'待有效评测'}</td></tr>`).join('')}</tbody></table></div></section>${r&&!r.pass&&!r.error?`<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>失败样本 · 红线漏判</h2></div><div class="panel-body"><p>case_B02：变体联系方式引流。人工标签：违规；模型结论：正常。</p>${button('定位并修正规则',"fromVersion(selectedVersion);toast('请开启识别变体联系方式，保存后固化新版本')",'small')}<p class="muted">覆盖正常、违规、边界与历史错误，不能仅用模型打分替代人工标签。</p></div></section>`:''}<div class="actions" style="margin-top:20px">${button('查看版本差异','versionDetails(selectedVersion)')}${v?.config.approval?button('申请指定审批',"act(()=>{E.approve(S,app(),selectedVersion,'申请');render();toast('已提交指定审批')})",'',!r?.pass||S.role!=='业务编辑者'):''}${button('前往发布管理',"go('release')",'primary')}</div>`}
function runEvaluation(fail=false){act(()=>{if(S.role!=='业务编辑者')throw Error('请切换业务编辑者');let v=selectedVersion;if(!v)throw Error('请先固化版本');E.evaluate(S,app(),v,fail);render();toast(fail?'评测执行失败':E.version(app(),v).report.pass?'评测通过':'评测未通过，发布被拦截')})}
function updateRule(){act(()=>{if(S.role!=='业务编辑者')throw Error('请切换业务编辑者');app().ruleRevision++;E.log(S,app(),'准入规则更新 r'+app().ruleRevision+'，历史报告保留但需按新规则重评');render();toast('准入规则已更新，发布前需重新评测')})}
function releases(){let a=app(),v=E.version(a,selectedVersion||a.candidate||a.production),reasons=E.gate(S,a,v?.id);return `<div class="review-toolbar">${versionPicker()}<div><b>测试与生产隔离</b><small>草稿调试不接收生产流量</small></div><span class="tag">PRODUCTION</span></div><div class="detail-grid"><section class="panel"><div class="panel-head"><h2>生产版本与流量</h2>${badge(a.active?'运行中':'未上线 / 已停用',a.active?'':'warning')}</div><div class="panel-body"><div class="fields-row"><div class="version-box"><span>稳定版本</span><h3>${a.production||'未上线'}</h3><div class="big">${a.active?100-a.grayPercent:0}%</div><p>${esc(E.version(a,a.production)?.config.knowledge||'版本依赖已固化')}</p></div><div class="version-box"><span>灰度版本</span><h3>${a.grayVersion||'—'}</h3><div class="big">${a.active?a.grayPercent:0}%</div><p>用户 ID 稳定分组 · 会话绑定版本</p></div></div><div class="traffic"><div style="width:${a.active?100-a.grayPercent:0}%"></div></div>${v?.config.gray?select('发布比例','ratio',[['10','10% 灰度'],['50','50% 灰度'],['100','100% 全量']],a.grayPercent===10?'50':'10'): '<p>所选版本配置：全量发布</p>'}<label class="switch-row"><input id="deploy-fail" type="checkbox">模拟部署失败（验证原生产保持不变）</label><div class="actions">${button('发布到生产','confirmDeploy()','primary',!!reasons.length)}${button('恢复有效旧版本','rollbackDialog()','',S.role!=='发布者')}${button(a.active?'停用服务':'恢复服务','toggleService()','danger',S.role!=='发布者')}</div><p class="muted">回退只改变新请求 / 新会话入口。已有会话继续绑定版本；若依赖失效或服务停用则转人工。</p></div></section><section class="panel"><div class="panel-head"><h2>发布准入</h2>${badge(reasons.length?'暂不可发布':'满足准入',reasons.length?'warning':'')}</div><div class="panel-body">${reasons.length?reasons.map(x=>`<div class="notice warning">${esc(x)}</div>`).join(''):'<div class="notice success">版本、静态检查、依赖有效性、评测、审批与发布角色均通过。</div>'}${v?.config.approval?`<h3>指定审批：${v.approval}</h3><p>审批必须绑定 ${v.id} 及其评测结论。</p>${button('通过 / 驳回','approvalDialog()','small',S.role!=='指定审批人'||v.approval!=='待审批')}`:''}<h3 style="margin-top:25px">依赖快照</h3><div class="chips" style="margin-top:12px">${v?E.deps(v.config).map(id=>`<span class="tag">${esc(id)}</span>`).join(''):''}</div></div></section></div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>发布与操作记录</h2></div>${auditTable(S.audit.filter(x=>x.appId===a.id))}</section>`}
function confirmDeploy(){let ratio=+(document.querySelector('#ratio')?.value||100),fail=document.querySelector('#deploy-fail').checked;modal('确认发布',`<p>目标 ${selectedVersion} · 生产流量 ${ratio}%</p><p>人工决定放量；短期点击不能替代留存。异常时保持原生产配置。</p>`,button('取消','closeModal()')+button('确认发布',`act(()=>{E.deploy(S,app(),selectedVersion,${ratio},${fail});closeModal();render();toast('版本与流量已同步')})`,'primary'))}
function approvalDialog(){let v=E.version(app(),selectedVersion);modal('指定审批 · '+v.id,`<p>评测：${v.report?.pass?'通过':'未通过'} · 固定依赖：${E.deps(v.config).join(' / ')}</p>${field('审批意见（必填）','approval-comment','')}<label class="switch-row"><input id="review-confirm" type="checkbox">已抽查正常、边界与历史错误样本</label>`,button('查看差异','versionDetails(selectedVersion)')+button('驳回',"decideApproval('驳回')")+button('通过',"decideApproval('通过')",'primary'))}
function decideApproval(decision){act(()=>{if(!document.querySelector('#approval-comment').value.trim())throw Error('请填写审批意见');if(decision==='通过'&&!document.querySelector('#review-confirm').checked)throw Error('请确认已抽查样本');E.approve(S,app(),selectedVersion,decision);closeModal();render()})}
function rollbackDialog(){modal('恢复版本及依赖快照',`<p>已有会话继续使用绑定版本；新会话使用恢复版本。失效政策 / 知识不可恢复。</p><div class="field"><label for="restore-version">恢复目标</label><select id="restore-version">${app().versions.filter(v=>v.report?.pass).map(v=>{let errors=E.dependencyErrors(S,v.config);return `<option value="${v.id}" ${errors.length?'disabled':''}>${v.id} · ${E.deps(v.config).join(' / ')} ${errors.length?'（'+esc(errors.join('；'))+'）':''}</option>`}).join('')}</select></div>`,button('取消','closeModal()')+button('确认恢复',"act(()=>{E.rollback(S,app(),document.querySelector('#restore-version').value);closeModal();render();toast('已恢复版本及完整依赖')})",'danger'))}
function toggleService(){modal(app().active?'停用服务':'恢复服务',`<p>停用时停止接收新请求与任务，未完成批项暂停；历史记录保留。恢复前会校验生产依赖。</p>`,button('取消','closeModal()')+button('确认',"act(()=>{if(S.role!=='发布者')throw Error('无发布权限');if(!app().active){let v=E.version(app(),app().production);if(!v)throw Error('没有生产版本');let errs=E.dependencyErrors(S,v.config);if(errs.length)throw Error(errs.join('；'))}app().active=!app().active;if(!app().active)S.batches.filter(b=>b.appId===appId).forEach(b=>{b.paused=true;b.items.filter(i=>i.status==='待处理').forEach(i=>i.status='暂停')});E.log(S,app(),app().active?'恢复服务':'停用服务，未完成任务暂停');closeModal();render()})",'primary'))}
function runs(){let a=app(),rows=S.runs.filter(r=>r.appId===a.id&&(runFilter==='全部'||r.environment===runFilter));return `<div class="stats">${stat('在线资源通道','独立','并发额度 100 · 示例配置','zap')}${stat('批量资源通道','独立','队列长度 '+S.batches.filter(b=>b.appId===a.id&&b.paused).length+' · 模拟','grid')}${stat('P95 延迟','842<small>ms</small>','预置指标，非真实容量验证','clock')}${stat('示例错误率','0.08<small>%</small>','模型成本 ¥386.2 · 24 小时示例','chart')}</div><section class="panel"><div class="panel-head"><h2>生产模拟调用</h2><div class="actions">${button('新请求 / 多轮会话','productionDialog()','primary small')}${button('模拟新增曝光','simulateExposure()','small')}${button('新老版本效果','effects()','small')}</div></div><div class="panel-body"><p class="subtitle">新请求按实际生产配置路由。稳定分组依据用户 ID；多轮会话固定 Agent 及知识版本。</p></div></section><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>执行记录 <span class="count">${rows.length}</span></h2><select aria-label="筛选环境" class="select select-inline" onchange="runFilter=this.value;render()">${options(['全部','测试','生产'],runFilter)}</select></div><div class="table-wrap"><table><thead><tr><th>请求 / 会话</th><th>环境 / 版本</th><th>状态</th><th>耗时</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="tag">${r.id}</span><small class="row-small">${r.sessionId||r.taskId||r.time}</small></td><td>${r.environment} · ${r.versionId||'r'+r.revision}</td><td>${badge(r.status,r.error?'warning':'')}</td><td>${r.duration} ms</td><td><button class="link" onclick="showRun('${r.id}')">实际路径与引用</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">尚无运行记录，先进行草稿调试或生产模拟调用。</td></tr>'}</tbody></table></div></section>`}
function productionDialog(sessionId=''){let sessions=S.sessions.filter(s=>s.appId===appId&&!s.closed);modal('生产模拟调用 / 会话',`${select('会话','session-choice',[['','新建会话 / 单次请求'],...sessions.map(s=>[s.id,s.id+' · '+s.versionId+' · '+s.history.length+' 轮'])],sessionId)}${field('用户 ID（稳定分流）','user-id','user-0099')}${field('业务问题','prod-input',aKind('C')?'这件衣服可以几天内退货？':aKind('B')?'请识别这条内容是否存在隐晦引流':'周末公园穿搭推荐')}<div id="prod-result"></div><p>继续已有会话沿用原版本；结束重建后采用当前生产版本。无效依赖将阻止自动回答。</p>`,button('结束选中会话','endSession()')+button('发送','sendProduction()','primary'))}
function sendProduction(){act(()=>{let r=E.productionRun(S,app(),document.querySelector('#prod-input').value,document.querySelector('#user-id').value,document.querySelector('#session-choice').value||null);let selected=r.sessionId;document.querySelector('#session-choice').innerHTML=options([['','新建会话 / 单次请求'],...S.sessions.filter(s=>s.appId===appId&&!s.closed).map(s=>[s.id,s.id+' · '+s.versionId+' · '+s.history.length+' 轮'])],selected);document.querySelector('#prod-result').innerHTML=`<div class="notice success">${r.versionId} · ${r.sessionId||'单次请求'} · 沿用绑定快照</div><pre class="code">${esc(JSON.stringify(r.output,null,2))}</pre>${r.dependencies.filter(x=>x.startsWith('kb@')||x.startsWith('policy@')).map(x=>`<button class="link" onclick="source('${x}')">查看引用 ${x}</button>`).join('')}<br><button class="link" onclick="showRun('${r.id}')">查看执行记录</button>`;})}
function endSession(){let id=document.querySelector('#session-choice').value;let s=S.sessions.find(s=>s.id===id);if(s)s.closed=true;persist();productionDialog();toast('旧会话已结束，新会话采用当前生产版本')}
function simulateExposure(){act(()=>{for(let user of ['user-100','user-199','user-2999','user-0099']){let r=E.productionRun(S,app(),'预置曝光请求',user);S.exposures.push({id:'exposure_'+(++S.seq),appId,user,versionId:r.versionId,experiment:'exp_'+appId})}render();toast('已生成 4 条稳定分组请求与曝光记录')})}
function baselineMetric(name){let p=E.version(app(),app().production),m=p?.report?.metrics.find(x=>x[0]===name);return m?m[1]+' '+m[3]:'—'}
function metricCount(m){return '<small class="row-small">'+(m[3]==='%'?Math.round(m[1]*5)+' / 500':m[3]==='条'?m[1]+' / 500 个样本':'500 次请求 P95')+'</small>'}
function reportHistory(){let v=E.version(app(),selectedVersion),reports=v?.reports||(v?.report?[v.report]:[]);modal('历史评测 · '+(v?.id||'无版本'),reports.length?reports.slice().reverse().map(r=>`<div class="dependency"><span><b>${r.id||'预置历史报告'}</b><br><small>${r.time||'预置'} · ${r.dataset} · 准入规则 r${r.rule}</small></span><span>${badge(r.error?'执行失败':r.pass?'通过':'未通过',r.pass?'':'error')}</span></div>`).join(''):'<p>暂无历史评测</p>')}
function effects(){let ex=S.exposures.filter(x=>x.appId===appId),versions=[...new Set(ex.map(x=>x.versionId))];modal('效果对比与事件回传',`<div class="notice warning">本次演示事件可实际关联曝光和版本。短期点击、采纳不代表留存；需要完整观察窗口和人工判断。</div><table><tr><th>版本</th><th>曝光数</th><th>点击率</th><th>采纳率</th><th>7 日留存</th></tr>${versions.map(v=>{let ids=ex.filter(x=>x.versionId===v).map(x=>x.id),clicks=new Set(S.feedback.filter(f=>ids.includes(f.exposureId)&&f.type==='click').map(f=>f.exposureId)).size,adopts=new Set(S.feedback.filter(f=>ids.includes(f.exposureId)&&f.type==='adopt').map(f=>f.exposureId)).size;return `<tr><td>${v}</td><td>${ids.length}</td><td>${clicks}/${ids.length} · ${(clicks/ids.length*100).toFixed(1)}%</td><td>${adopts}/${ids.length} · ${(adopts/ids.length*100).toFixed(1)}%</td><td>窗口未满</td></tr>`}).join('')||'<tr><td colspan="5">先点击运行记录中的「模拟新增曝光」</td></tr>'}</table><h3 style="margin:20px 0">模拟业务事件回传</h3>${select('关联曝光','event-exposure',ex.map(x=>[x.id,x.id+' · '+x.user+' · '+x.versionId]),ex[0]?.id||'')}${select('事件类型','event-type',[['click','点击'],['adopt','采纳']],'click')}${field('事件 ID（重复上报不重复计数）','event-id','event-'+(S.feedback.length+1))}<p class="muted">去重口径：事件 ID；展示率以去重后的曝光事件为分母，同一曝光同类型仅计一次。</p>`,button('关闭','closeModal()')+button('回传事件','sendFeedback()','primary',!ex.length))}
function sendFeedback(){act(()=>{let result=E.feedback(S,document.querySelector('#event-exposure').value,document.querySelector('#event-type').value,document.querySelector('#event-id').value);effects();toast(result.dedup?'事件已存在，重复上报已去重':'事件已关联实验、版本与曝光')})}

function batches(){let a=app(),list=S.batches.filter(b=>b.appId===appId),v=E.version(a,a.production);return `<div class="notice">批任务使用提交时的 Agent 与政策版本；按任务标识和内容 ID 保存唯一结果。在线与批量资源隔离。</div><section class="panel"><div class="panel-head"><h2>提交演示批次</h2></div><div class="panel-body"><div class="fields-row">${field('幂等批次标识','batch-key','review-batch-01')}${select('批次类型','batch-type',[['normal','5 条 · 3 成功 / 2 失败'],['legacy','旧政策批次 · 2 完成 / 3 待处理']],'normal')}</div><div class="actions">${button('提交批任务','submitBatch()','primary',v?.config.execution!=='batch')}${v?.config.execution!=='batch'?'<span class="muted">当前生产未开启批量执行，可在草稿中独立配置后发布。</span>':''}</div></div></section>${list.map(b=>`<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>${b.id} ${badge(b.paused?'暂停':b.items.every(x=>x.status==='成功')?'完成':'需处理',b.paused?'warning':'')}</h2><span class="tag">${b.versionId} / ${b.policy||'无政策'}</span></div><div class="panel-body"><p>批次 ${esc(b.key)} · 唯一结果 ${b.items.filter(x=>x.result).length}/5 · 去重命中 ${b.dedup} 次</p><div class="table-wrap"><table><tr><th>内容 ID</th><th>状态</th><th>尝试次数</th><th>错误 / 结论</th></tr>${b.items.map(i=>`<tr><td>${i.id}</td><td>${i.status}</td><td>${i.attempts}</td><td>${i.error||i.result?.category||'等待处理'} ${i.runId?`<button class="link" onclick="showRun('${i.runId}')">追踪 →</button>`:''}</td></tr>`).join('')}</table></div><div class="actions" style="margin-top:15px">${button('仅重试失败项',`act(()=>{E.retry(S,app(),S.batches.find(b=>b.id==='${b.id}'));render()})`,'small',b.paused||!b.items.some(i=>i.status==='失败'))}${button('暂停项转人工',`humanBatch('${b.id}')`,'small',!b.paused)}</div></div></section>`).join('')}`}
function submitBatch(){act(()=>{let b=E.batch(S,app(),document.querySelector('#batch-key').value.trim(),document.querySelector('#batch-type').value==='legacy');if(!b.key)throw Error('请填写批次标识');render();toast(b.dedup?'重复提交已去重，返回原任务':'批任务已创建')})}
function humanBatch(id){let b=S.batches.find(b=>b.id===id);b.items.filter(i=>i.status==='暂停').forEach(i=>{i.status='待人工';i.error='POLICY_EXPIRED_OR_PAUSED'});E.log(S,app(),id+' 未完成项转人工');persist();render()}
function knowledge(){return `<div class="heading"><div><div class="eyebrow">SHARED ASSETS</div><h1>知识与政策</h1><p class="subtitle">显式绑定快照，更新不覆盖生产依赖。</p></div>${button('模拟导入新快照','importKnowledge()','primary')}</div><div class="asset-grid">${S.assets.filter(x=>['knowledge','policy'].includes(x.type)).map(x=>`<section class="panel asset-card"><div class="panel-head"><h2>${esc(x.name)}</h2>${badge(x.valid?'有效':'已失效',x.valid?'':'error')}</div><div class="panel-body"><span class="tag">${x.id}</span><p>${esc(x.text)}</p><div class="actions">${button('查看 / 检索测试',`source('${x.id}')`,'small')}${button('绑定到草稿',`bindAsset('${x.id}')`,'small',!x.valid)}${button('标记失效',`invalidateDialog('${x.id}')`,'danger small',!x.valid)}</div></div></section>`).join('')}</div>`}
function source(id){let x=S.assets.find(x=>x.id===id);if(!x)return toast('找不到引用快照');modal('引用快照 · '+id,`<div class="notice ${x.valid?'success':'error'}">${x.valid?'快照有效':'快照已失效，不可用于新调用或版本恢复'}</div><h3>${esc(x.name)}</h3><p>${esc(x.text)}</p>${field('检索测试','retrieval-query','退货期限')}<div id="retrieval-result"></div>`,button('检索',`searchSource('${id}')`)+button('关闭','closeModal()'))}
function searchSource(id){let x=S.assets.find(x=>x.id===id),q=document.querySelector('#retrieval-query').value.trim();if(!q)return toast('请输入检索问题');document.querySelector('#retrieval-result').textContent=x.valid?'模拟检索结果：'+x.id+' · '+x.text:'快照已失效，禁止检索';}
function bindAsset(id){modal('将快照用于候选草稿',`${select('目标应用','asset-app',S.apps.map(a=>[a.id,a.name]),appId)}<p>只修改草稿并清除当前候选关联。生产和历史报告保持原快照。</p>`,button('取消','closeModal()')+button('绑定草稿',`act(()=>{if(S.role!=='业务编辑者')throw Error('请切换业务编辑者');let a=S.apps.find(x=>x.id===document.querySelector('#asset-app').value),c=E.copy(a.draft);c.knowledge='${id}';E.save(S,a,c);closeModal();go('build',a.id)})`,'primary'))}
function invalidateDialog(id){modal('标记快照失效',`<p>${id} 失效后，相关版本禁止发布与恢复，相关新调用被阻止；未完成批项暂停，保留既有结果供追溯。</p>`,button('取消','closeModal()')+button('确认失效',`act(()=>{if(S.role!=='发布者')throw Error('请切换发布者处理生效状态');E.invalidate(S,'${id}');closeModal();render()})`,'danger'))}
function importKnowledge(){modal('模拟导入知识 / 政策',`${select('类型','asset-type',[['knowledge','知识'],['policy','政策']],'knowledge')}${field('名称','asset-name','售后政策补充')}<div class="field"><label for="asset-content">快照内容</label><textarea id="asset-content">活动商品支持 15 天无理由退货，具体条件由客服核实。</textarea></div><p>此处将文本保存为新快照，不调用外部系统，不自动修改应用。</p>`,button('取消','closeModal()')+button('生成新快照','commitKnowledge()','primary'))}
function commitKnowledge(){act(()=>{if(S.role!=='业务编辑者')throw Error('请切换业务编辑者');let type=document.querySelector('#asset-type').value,name=document.querySelector('#asset-name').value.trim(),text=document.querySelector('#asset-content').value.trim();if(!name||!text)throw Error('名称和内容必填');let prefix=type==='policy'?'policy@':'kb@',num=1+Math.max(0,...S.assets.filter(x=>x.id.startsWith(prefix)).map(x=>+x.id.split('@')[1]));S.assets.push({id:prefix+num,type,name,text,valid:true});closeModal();render();toast('已生成 '+prefix+num+'，生产未改变')})}
function assets(){return `<div class="heading"><div><div class="eyebrow">REUSABLE CAPABILITIES</div><h1>模板与接入资产</h1><p class="subtitle">模板可编辑，Skill 显式绑定，外部服务按契约接入。</p></div>${button('注册受控服务','registerService()','primary')}</div><div class="asset-grid"><section class="panel"><div class="panel-head"><h2>共享流程模板</h2></div><div class="panel-body">${S.templates.map(t=>`<div class="dependency"><span><b>${esc(t.name)}</b><br><small>${esc(t.id)} · ${t.config.nodes.length} 节点</small></span><span>${button('使用',`createDialog('${t.id}')`,'small')}</span></div>`).join('')}<p class="muted">复制模板后独立编辑。后续模板变更不热更新应用。</p></div></section><section class="panel"><div class="panel-head"><h2>Skill 与工具版本</h2></div><div class="panel-body">${S.assets.filter(x=>['skill','tool'].includes(x.type)).map(x=>`<div class="dependency"><span><b>${esc(x.name)}</b><br><small>${x.id} · ${x.type==='skill'?'说明与参考资料':'只读工具 · 密钥 ••••'}</small></span><span>${x.type==='skill'?button('发布新版本',`upgradeSkill('${x.id}')`,'small'):button(x.authorized?'撤销授权':'恢复授权',`toggleTool('${x.id}')`,'small')}</span></div>`).join('')}<div class="notice">Skill 不自动选择或组合，不执行脚本；数据与工具权限由平台检查。</div></div></section><section class="panel wide"><div class="panel-head"><h2>已注册受控服务</h2><span class="tag">不托管任意代码</span></div><div class="panel-body">${S.services.length?S.services.map(x=>`<div class="dependency"><span><b>${esc(x.name)} · ${esc(x.id)}</b><br><small>${esc(x.url)} · 追踪字段 ${esc(x.trace)}</small></span><span>${button('模拟契约测试',`testService('${x.id}')`,'small')}</span></div>`).join(''):'<p class="muted">暂无注册服务，可注册已部署服务的版本化接口。</p>'}<p>平台只观察接口输入、输出、耗时和 externalTraceId，不展示虚构的服务内部节点。</p></div></section></div>`}
function upgradeSkill(id){act(()=>{if(S.role!=='业务编辑者')throw Error('请切换业务编辑者');let x=S.assets.find(x=>x.id===id),prefix=id.split('@')[0],num=1+Math.max(...S.assets.filter(x=>x.id.startsWith(prefix+'@')).map(x=>+x.id.split('@')[1]));S.assets.push({...E.copy(x),id:prefix+'@'+num,text:x.text+' 增加引用复核说明。'});render();toast('新增 Skill 版本，现有绑定保持不变')})}
function toggleTool(id){act(()=>{if(S.role!=='发布者')throw Error('请切换发布者管理演示授权');let x=S.assets.find(x=>x.id===id);x.authorized=!x.authorized;render();toast(x.authorized?'已恢复工具授权':'已撤销授权，相关调用与发布将被拦截')})}
function registerService(){modal('注册版本化服务接口',`${field('服务名称','svc-name','受控业务 Agent')}${field('服务版本 ID','svc-id','service-demo@1')}${field('接口地址（仅模拟调用）','svc-url','https://service.example.invalid/agent')}${field('输入契约 JSON','svc-input','{"text":"string"}')}${field('输出契约 JSON','svc-output','{"answer":"string"}')}${field('外部追踪字段','svc-trace','externalTraceId')}<p>鉴权采用托管服务身份；不填写真实密钥。不会向此 URL 发出网络请求。</p>`,button('取消','closeModal()')+button('校验并注册','commitService()','primary'))}
function commitService(){act(()=>{if(S.role!=='业务编辑者')throw Error('请切换业务编辑者');let get=id=>document.querySelector(id).value.trim(),id=get('#svc-id'),name=get('#svc-name'),url=get('#svc-url'),trace=get('#svc-trace');if(!/^[a-z][a-z0-9-]*@\d+$/.test(id)||S.services.some(x=>x.id===id))throw Error('服务 ID 需为唯一 name@数字');if(!name||!trace||!url.startsWith('https://'))throw Error('填写名称、HTTPS 地址和追踪字段');let input=JSON.parse(get('#svc-input')),output=JSON.parse(get('#svc-output'));for(let schema of [input,output])if(!schema||typeof schema!=='object'||Array.isArray(schema)||!Object.keys(schema).length||Object.values(schema).some(v=>!['string','number','boolean','object','array'].includes(v)))throw Error('契约使用合法字段类型');S.services.push({id,name,url,trace,input,output,valid:true,authorized:true});closeModal();render();toast('版本化接口已注册')})}
function testService(id){let svc=S.services.find(x=>x.id===id);modal('模拟契约测试',`<div class="notice success">接口声明有效 · ${esc(svc.id)} · Mock 调用成功</div><pre class="code">${esc(JSON.stringify({input:svc.input,output:svc.output,externalTraceId:'ext_demo_001',durationMs:428},null,2))}</pre><p>仅显示调用边界，平台不掌握外部服务内部节点。</p>`)}
function saveTemplateDialog(){if(dirty)return toast('请先保存草稿');modal('保存为共享流程模板',field('模板名称','template-name',app().name+' 可复用流程'),button('取消','closeModal()')+button('保存模板',"act(()=>{if(S.role!=='业务编辑者')throw Error('请切换业务编辑者');let name=document.querySelector('#template-name').value.trim();if(!name)throw Error('名称必填');let c=E.copy(app().draft);if(E.check(c,S).length)throw Error('静态检查通过后再共享');S.templates.push({id:'shared-'+(++S.seq)+'@1',name,config:c});closeModal();toast('已保存共享模板，可用于创建新应用')})",'primary'))}
function createDialog(template=''){modal('创建应用',`${field('应用名称','new-name','')}${ownerField('new-owner','')}${select('构建入口','new-mode',[['simple','简单配置'],['flow','基础编排'],['service','受控服务接入']],template?'flow':'simple')}${select('起点 / 任务模式','new-template',[['blank','空白画布'],['single','内置单次模型'],['rag','内置检索问答'],...S.templates.map(t=>[t.id,t.name+' · '+t.id])],template||'single')}${select('执行方式','new-execution',[['online','在线'],['batch','批量']],'online')}<label class="switch-row"><input id="new-sessions" type="checkbox">启用会话上下文</label><label class="switch-row"><input id="new-approval" type="checkbox">需指定审批</label><label class="switch-row"><input id="new-gray" type="checkbox">支持灰度</label><p>应用创建后仍可在工作台重命名或删除。</p>`,button('取消','closeModal()')+button('创建并配置','commitCreate()','primary'))}
function commitCreate(){act(()=>{if(S.role!=='业务编辑者')throw Error('请切换业务编辑者');let get=id=>document.querySelector(id),name=get('#new-name').value.trim(),owner=get('#new-owner').value,t=get('#new-template').value,mode=get('#new-mode').value;if(!name||!owner||S.apps.some(a=>a.name===name))throw Error('名称、责任人必填且项目内唯一');let template=S.templates.find(x=>x.id===t),kind=t==='single'?'B':t==='rag'?'C':template?.config.knowledge?.startsWith('policy')?'B':template?.config.knowledge?.startsWith('kb')?'C':'A';let c=template?E.copy(template.config):E.config(kind);c.mode=mode;c.template=template?.id||'';if(t==='blank'){c.nodes=[];c.edges=[]}if(mode==='simple'&&t==='blank')throw Error('空白画布请使用基础编排入口');if(mode==='service'){c.nodes=[];c.edges=[];c.service='';}c.execution=get('#new-execution').value;c.sessions=get('#new-sessions').checked;c.approval=get('#new-approval').checked;c.gray=get('#new-gray').checked;let id='app'+(++S.seq);S.apps.push({id,name,owner,kind,team:'业务公共空间',draft:c,revision:1,versions:[],candidate:null,production:null,grayVersion:null,grayPercent:0,active:false,dataset:'ds-'+kind.toLowerCase()+'@1',ruleRevision:1});closeModal();go('build',id);toast('应用已创建，尚未上线')})}
function auditTable(rows){return `<div class="table-wrap"><table><thead><tr><th>时间</th><th>应用 / 角色</th><th>变更</th></tr></thead><tbody>${rows.slice(0,30).map(x=>`<tr><td>${esc(x.time)}</td><td>${esc(x.name)}<small class="row-small">${esc(x.role)}</small></td><td class="wrap-cell">${esc(x.text)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">暂无本次评审操作</td></tr>'}</tbody></table></div>`}
function audit(){return `<div class="heading"><div><div class="eyebrow">GOVERNANCE</div><h1>权限与审计</h1><p class="subtitle">顶部角色仅用于演示权限边界，不是真实身份认证。</p></div></div><div class="stats">${stat('业务编辑者','构建','草稿 · 固化 · 评测 · 申请审批')}${stat('指定审批人','审批','处理待审批版本，独立于发布')}${stat('发布者','发布','流量 · 恢复 · 停用 · 授权')}${stat('审计事件',S.audit.length,'记录版本、依赖与操作')}</div><section class="panel">${auditTable(S.audit)}</section>`}
function sampleDialog(id){let r=S.runs.find(x=>x.id===id);modal('确认问题样本',`${field('人工标签 / 正确答案','sample-label','')}<label class="switch-row"><input id="sample-scrub" type="checkbox">已脱敏并人工确认内容</label><p>加入下一版评测集草稿，当前固定数据集不被静默修改。</p>`,button('取消','closeModal()')+button('加入评测集',`act(()=>{let label=document.querySelector('#sample-label').value.trim();if(!label||!document.querySelector('#sample-scrub').checked)throw Error('请填写人工标签并确认脱敏');if(S.samples.some(s=>s.runId==='${id}'))throw Error('此运行记录已加入样本');S.samples.push({runId:'${id}',appId:'${r.appId}',label});E.log(S,app(),'确认问题样本 ${id} 加入下一版评测集草稿');closeModal();toast('样本已加入，当前评测集保持不变')})`,'primary'))}
function guide(){modal('PRD V1.3 评审路径',`<p><b>A：</b>编辑检索条件或分支 → 保存 → 静态检查与正常/无结果试运行 → 固化 → 评测 → 切换发布者 → 灰度 → 运行记录 → 回退。</p><p><b>B：</b>固化 policy@2 → 评测失败 → 修正变体联系方式规则 → 保存并重新固化 → 评测 → 申请审批 → 指定审批人通过 → 发布者上线 → 批任务失败项重试。</p><p><b>C：</b>简单问答 → 转换流程并添加物流分支 → 超时兜底调试 → 绑定 kb@2 → 保存、固化、回归 → 发布 → 新旧会话版本验证。</p><p><b>通用：</b>从空白建图；保存共享模板；绑定 Skill 固定版本；注册受控服务并测试接口契约。</p><p>刷新保留本地状态。指标、业务输出与耗时均为确定性示例，不能用于生产验收。</p>`)}
function resetDemo(){modal('重置演示数据',`<p>将清除本机本 Demo 的草稿、版本、运行和审计记录，恢复 V1.3 初始场景。不会修改 PRD 文档。</p>`,button('取消','closeModal()')+button('确认重置',"S=E.initial();dirty=false;buffer=null;persist();closeModal();go('list','A')",'danger'))}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
window.addEventListener('hashchange',()=>{let [p,id]=location.hash.slice(1).split('/');p=({config:'build',monitor:'runs'})[p]||p;if(pageNames[p]&&(p!==page||id&&id!==appId)){if(dirty){location.hash=page+'/'+appId;return toast('请先保存或放弃当前草稿')}page=p;if(S.apps.some(a=>a.id===id))appId=id;buffer=p==='build'?E.copy(app().draft):null;selectedVersion=app().candidate||app().production;render()}});
let [p,id]=location.hash.slice(1).split('/');page=({config:'build',monitor:'runs'})[p]||p||'list';if(!pageNames[page])page='list';if(S.apps.some(a=>a.id===id))appId=id;if(page==='build')buffer=E.copy(app().draft);selectedVersion=app().candidate||app().production;render();



